#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        int temp;
        cin >> temp;
        a[i] = temp % m;
    }
    unordered_set<int> x, y;

    function<void(unordered_set<int>&, int, int, int)> generate_subsets = [&](unordered_set<int>& s, int length, int index, int current_sum) {
        if (index == length) {
            s.insert(current_sum);
        } else {
            generate_subsets(s, length, index + 1, (current_sum + a[index]) % m);
            generate_subsets(s, length, index + 1, current_sum);
        }
    };

    int half = n / 2;
    generate_subsets(x, half, 0, 0);
    generate_subsets(y, n - half, half, 0);
    vector<int> y_vec(y.begin(), y.end());
    sort(y_vec.begin(), y_vec.end());

    int result = 0;
    for (auto i : x) {
        int pos = (int)(std::lower_bound(y_vec.begin(), y_vec.end(), m - i) - y_vec.begin());
        if (pos > 0) {
            int candidate = i + y_vec[pos - 1];
            if (candidate > result) {
                result = candidate;
            }
        }
    }
    cout << result << "\n";
    return 0;
}
